import{_ as r,o,c as l,ae as i}from"./chunks/framework.RRduUuAx.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-架构设计-架构风格与模式","description":"","frontmatter":{"title":"架构师-备考 综合知识-架构设计-架构风格与模式"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式.md","filePath":"综合知识/架构设计/架构风格与模式.md"}'),n={name:"综合知识/架构设计/架构风格与模式.md"};function a(e,t,s,d,g,h){return o(),l("div",null,[...t[0]||(t[0]=[i('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 软件架构风格定义与五大分类（数据流/调用返回/独立构件/虚拟机/仓库）</li><li>[x] 经典风格详解：管道-过滤器/批处理/主程序子程序/面向对象/层次结构</li><li>[x] 独立构件风格：进程通信/事件驱动（隐式调用）</li><li>[x] 虚拟机风格：解释器/基于规则的系统</li><li>[x] 仓库风格：数据库系统/黑板系统/超文本系统</li><li>[x] C2 体系结构风格</li><li>[x] 闭环控制（过程控制）风格</li><li>[x] C/S、B/S、多层架构</li><li>[x] MVC / MVP / MVVM</li><li>[x] 富互联网应用（RIA）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、软件架构风格概述" tabindex="-1">一、软件架构风格概述 <a class="header-anchor" href="#一、软件架构风格概述" aria-label="Permalink to &quot;一、软件架构风格概述&quot;">​</a></h3><blockquote><p><strong>软件体系结构风格</strong>是描述某一特定应用领域中系统组织方式的<strong>惯用模式</strong>。架构风格定义一个系统家族，即<strong>一个架构定义、一个词汇表和一组约束</strong>。词汇表中包含一些构件和连接件类型，这组约束指出系统如何将这些构件和连接件组合起来。</p></blockquote><p><strong>核心要点：</strong></p><ul><li>架构风格反映了领域中众多系统所共有的<strong>结构和语义特性</strong></li><li>指导如何将各个模块和子系统有效组织成完整系统</li><li>架构设计的核心问题是<strong>能否达到架构级的软件复用</strong></li><li>架构风格定义了用于描述系统的<strong>术语表</strong>和一组<strong>指导构建系统的规则</strong></li></ul><hr><h3 id="二、五大架构风格分类-★" tabindex="-1">二、五大架构风格分类 ★ <a class="header-anchor" href="#二、五大架构风格分类-★" aria-label="Permalink to &quot;二、五大架构风格分类 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风格类别</th><th>核心特点</th><th>代表</th></tr></thead><tbody><tr><td><strong>数据流风格</strong></td><td>面向数据流，按顺序从前向后执行</td><td>批处理序列、管道-过滤器</td></tr><tr><td><strong>调用/返回风格</strong></td><td>构件间存在显式调用关系</td><td>主程序/子程序、面向对象、层次结构</td></tr><tr><td><strong>独立构件风格</strong></td><td>构件独立，通过事件/异步触发</td><td>进程通信、事件驱动（隐式调用）</td></tr><tr><td><strong>虚拟机风格</strong></td><td>自定义规则供使用者使用，跨平台适配</td><td>解释器、基于规则的系统</td></tr><tr><td><strong>仓库风格</strong></td><td>以数据为中心，所有操作围绕数据中心</td><td>数据库系统、超文本系统、黑板系统</td></tr></tbody></table><hr><h3 id="三、数据流风格详解" tabindex="-1">三、数据流风格详解 <a class="header-anchor" href="#三、数据流风格详解" aria-label="Permalink to &quot;三、数据流风格详解&quot;">​</a></h3><p><strong>批处理序列：</strong></p><ul><li>构件为一系列固定顺序的计算单元，构件之间<strong>只通过数据传递交互</strong></li><li>每个处理步骤是独立程序，<strong>每一步必须在前一步结束后才能开始</strong></li><li>数据必须是完整的，以<strong>整体</strong>方式传递</li><li>前后构件不一定有关联</li></ul><p><strong>管道-过滤器：</strong></p><ul><li>每个构件有一组输入输出，读取输入数据流，处理后产生输出数据流</li><li><strong>前一个构件的输出作为后一个构件的输入</strong>，前后数据流关联</li><li>过滤器 = 构件，管道 = 连接件</li><li>早期编译器采用此风格</li></ul><blockquote><p><strong>二者区别</strong>：批处理前后构件不一定关联且作为整体传递（必须前一个执行完）；管道-过滤器是前一个输出作为后一个输入（前面执行到部分即可开始下一个）。</p></blockquote><hr><h3 id="四、调用-返回风格详解" tabindex="-1">四、调用/返回风格详解 <a class="header-anchor" href="#四、调用-返回风格详解" aria-label="Permalink to &quot;四、调用/返回风格详解&quot;">​</a></h3><p><strong>主程序/子程序：</strong> 单线程控制，把问题划分为处理步骤，构件即主程序和子程序，过程调用作为交互机制。</p><p><strong>面向对象：</strong> 构件是对象（抽象数据类型的实例），连接件是对象间交互方式（函数和过程调用）。</p><p><strong>层次结构：</strong></p><ul><li>构件组成层次结构，每层为上一层提供服务，使用下一层服务</li><li>只能见到与自己邻接的层</li><li><strong>修改某一层，最多影响相邻两层（通常只影响上层）</strong></li></ul><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>支持基于可增加抽象层的设计，可将复杂问题分解为增量步骤</td><td>并非每个系统都可划分为分层模式</td></tr><tr><td>不同层次处于不同抽象级别</td><td>很难找到合适的层次抽象方法</td></tr><tr><td>只要相邻层接口相同，每层可用不同方法实现，支持软件复用</td><td>层次通信效率相对较低（需从高到低再回到高）</td></tr></tbody></table><blockquote><p>分层架构两大脆弱性：底层错误会导致整个系统无法正常运行；层间引入通信机制会造成性能下降。</p></blockquote><hr><h3 id="五、独立构件风格详解" tabindex="-1">五、独立构件风格详解 <a class="header-anchor" href="#五、独立构件风格详解" aria-label="Permalink to &quot;五、独立构件风格详解&quot;">​</a></h3><p><strong>进程通信：</strong> 构件是独立的进程，连接件是消息传递。消息传递方式：点对点、异步/同步、远程过程调用等。</p><p><strong>事件驱动系统（隐式调用）：</strong></p><ul><li>构件不直接调用过程，而是<strong>触发或广播</strong>一个或多个事件</li><li>构件中的过程在事件中注册，事件触发时系统<strong>自动调用注册的过程</strong></li><li>优点：为软件复用提供强大支持，便于构件维护和演化</li><li>缺点：构件放弃了对系统计算的控制</li></ul><hr><h3 id="六、虚拟机风格详解" tabindex="-1">六、虚拟机风格详解 <a class="header-anchor" href="#六、虚拟机风格详解" aria-label="Permalink to &quot;六、虚拟机风格详解&quot;">​</a></h3><p><strong>解释器：</strong></p><ul><li>组成：完成解释工作的<strong>解释引擎</strong> + 存储被解释代码的<strong>存储区</strong> + 记录引擎工作状态的<strong>数据结构</strong> + 记录执行进度的数据结构</li><li>缺点：执行效率低</li></ul><p><strong>基于规则的系统：</strong></p><ul><li>组成：规则集、规则解释器、规则/数据选择器、<strong>工作内存</strong></li><li>一般用在**人工智能领域和 DSS（决策支持系统）**中</li><li>适合业务规则频繁变化的场景</li></ul><blockquote><p><strong>考题套路</strong>：业务灵活组合、自定义规则 → 虚拟机风格。其中规则系统偏向专家系统，解释器偏向自定义逻辑执行。</p></blockquote><hr><h3 id="七、仓库-数据共享-风格详解" tabindex="-1">七、仓库（数据共享）风格详解 <a class="header-anchor" href="#七、仓库-数据共享-风格详解" aria-label="Permalink to &quot;七、仓库（数据共享）风格详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>组成与特点</th><th>应用领域</th></tr></thead><tbody><tr><td><strong>数据库系统</strong></td><td>中央共享数据源 + 多个独立处理单元</td><td>通用数据管理</td></tr><tr><td><strong>黑板系统</strong></td><td>知识源 + 黑板（全局数据库）+ 控制</td><td>信号处理、问题规划、编译器优化等<strong>无确定性算法</strong>的场景</td></tr><tr><td><strong>超文本系统</strong></td><td>网状链接，用户可按联想跳转</td><td>互联网</td></tr></tbody></table><blockquote><p>现代编译器的集成开发环境一般采用<strong>数据仓库</strong>（以数据为中心的架构风格）进行开发，中心数据即程序的语法树。</p></blockquote><hr><h3 id="八、c2-体系结构风格" tabindex="-1">八、C2 体系结构风格 <a class="header-anchor" href="#八、c2-体系结构风格" aria-label="Permalink to &quot;八、C2 体系结构风格&quot;">​</a></h3><blockquote><p>C2 风格概括为：<strong>通过连接件绑定在一起的按照一组规则运作的并行构件网络</strong>。</p></blockquote><p><strong>组织规则：</strong></p><ol><li>系统中的构件和连接件都有一个顶部和一个底部</li><li>构件的顶部应连接到某连接件的底部，构件底部应连接到某连接件的顶部，<strong>构件与构件之间不允许直接连接</strong></li><li>一个连接件可以和任意数目的其它构件和连接件连接</li><li>两个连接件直接连接时，必须由其中一个的底部到另一个的顶部</li></ol><hr><h3 id="九、闭环控制-过程控制-风格" tabindex="-1">九、闭环控制（过程控制）风格 <a class="header-anchor" href="#九、闭环控制-过程控制-风格" aria-label="Permalink to &quot;九、闭环控制（过程控制）风格&quot;">​</a></h3><p>当软件被用来操作一个物理系统时，软件与硬件之间粗略表示为一个<strong>反馈循环</strong>。通过接受一定输入，确定一系列输出，最终使环境达到新状态。适合于<strong>嵌入式系统</strong>，涉及连续的动作与状态。</p><blockquote><p>典型场景：空调温控、轿车巡航定速、机器人运动控制等需要持续测量-比较-调节的场景。</p></blockquote><hr><h3 id="十、c-s、b-s-与多层架构" tabindex="-1">十、C/S、B/S 与多层架构 <a class="header-anchor" href="#十、c-s、b-s-与多层架构" aria-label="Permalink to &quot;十、C/S、B/S 与多层架构&quot;">​</a></h3><p><strong>两层 C/S 架构：</strong></p><ul><li>客户端和服务器都有处理功能，现已不常用</li><li>缺点：开发成本高、客户端复杂、维护升级困难、安全性问题、难以复用</li></ul><p><strong>三层 C/S 架构：</strong></p><ul><li>表示层（客户机）+ 功能层（应用服务器）+ 数据层（数据库服务器）</li><li>将处理功能独立出来</li></ul><table tabindex="0"><thead><tr><th>优点</th></tr></thead><tbody><tr><td>各层逻辑独立，系统结构清晰，提高可维护性和可扩展性</td></tr><tr><td>允许灵活选用相应平台和硬件，良好的可升级性和开放性</td></tr><tr><td>各层可并行开发，可选用各自最适合的开发语言</td></tr><tr><td>功能层有效隔离表示层与数据层，安全管理层次更合理可控</td></tr></tbody></table><blockquote><p>三层 C/S 关键在于<strong>各层之间的通信效率</strong>，要慎重考虑通信方法、通信频度和数据量。</p></blockquote><p><strong>三层 B/S 架构：</strong></p><ul><li>三层 C/S 的变种：客户端变为浏览器，应用服务器变为 WEB 服务器</li><li>又称<strong>0 客户端架构</strong></li><li>缺点：缺乏动态页面支持、安全性难控制、响应速度远低于 C/S、数据动态交互性不强</li></ul><p><strong>混合架构：</strong></p><ul><li>内外有别模型：内部 C/S，外部 B/S</li><li>查改有别模型：B/S 查询，C/S 修改</li><li>缺点：实现困难且成本高</li></ul><p><strong>富互联网应用（RIA）：</strong></p><ul><li>弥补 B/S 架构问题，本质还是网站模式</li><li>结合 C/S 反应速度快、交互性强 + B/S 传播范围广</li><li>数据能缓存在客户端，减少服务器往返</li><li>本质仍是 0 客户端，借助高速网速实现必要插件本地快速缓存（如小程序）</li></ul><hr><h3 id="十一、mvc-mvp-mvvm" tabindex="-1">十一、MVC / MVP / MVVM <a class="header-anchor" href="#十一、mvc-mvp-mvvm" aria-label="Permalink to &quot;十一、MVC / MVP / MVVM&quot;">​</a></h3><p><strong>MVC 架构：</strong></p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th></tr></thead><tbody><tr><td><strong>控制器</strong>（Controller）</td><td>处理用户交互，从视图读取数据，控制用户输入，向模型发送数据</td></tr><tr><td><strong>模型</strong>（Model）</td><td>处理应用程序数据逻辑，负责数据库存取，表示业务数据和业务逻辑</td></tr><tr><td><strong>视图</strong>（View）</td><td>处理数据显示，用户看到并交互的界面，不进行实际业务处理</td></tr></tbody></table><p><strong>MVP：</strong> 将 MVC 的 Controller 换为 Presenter（呈现），<strong>完全切断 View 与 Model 的联系</strong>，由 Presenter 充当桥梁。View 非常薄（被动视图），Presenter 非常厚（所有逻辑）。</p><p><strong>MVVM：</strong></p><ul><li>低耦合：View 可独立于 Model 变化，一个 ViewModel 可绑定到不同 View</li><li>可重用性：视图逻辑放在 ViewModel 中，多个 View 重用</li><li>独立开发：开发人员专注业务逻辑，设计人员专注页面</li><li>可测试：测试可针对 ViewModel 编写</li></ul>',71)])])}const p=r(n,[["render",a]]);export{b as __pageData,p as default};
